const description: { en: string; ja: string } = {"en":"Three hollyhock leaves meet at their points in the middle. The outer portions alternate clipped leaves with curved stalks inside the round edge.","ja":"葵の葉を三枚置き、葉先を中央で合わせます。丸い外縁の内側には切り分けた片葉と曲がった茎を交互に置きます。"};

